use std::collections::HashSet;
use std::fmt;

/// Classification label indicating where data originated or what kind it is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TaintLabel {
    /// Data received from a network source.
    Network,
    /// Data provided directly by the user.
    UserInput,
    /// Data from shell command output.
    ShellOutput,
    /// Data from sensitive environment variables (API keys, tokens, etc.).
    SecretEnv,
    /// Data generated by an LLM.
    LlmOutput,
    /// Data read from a file.
    FileContent,
}

impl fmt::Display for TaintLabel {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Network => write!(f, "Network"),
            Self::UserInput => write!(f, "UserInput"),
            Self::ShellOutput => write!(f, "ShellOutput"),
            Self::SecretEnv => write!(f, "SecretEnv"),
            Self::LlmOutput => write!(f, "LlmOutput"),
            Self::FileContent => write!(f, "FileContent"),
        }
    }
}

/// A value annotated with taint labels tracking its provenance.
#[derive(Debug, Clone)]
pub struct TaintedValue {
    /// The actual data.
    pub value: String,
    /// Set of labels indicating data origins.
    pub labels: HashSet<TaintLabel>,
    /// Human-readable description of where this value came from.
    pub source: String,
}

impl TaintedValue {
    /// Create a new tainted value with a single label.
    pub fn new(value: impl Into<String>, label: TaintLabel, source: impl Into<String>) -> Self {
        let mut labels = HashSet::new();
        labels.insert(label);
        Self {
            value: value.into(),
            labels,
            source: source.into(),
        }
    }

    /// Add an additional taint label.
    pub fn add_label(&mut self, label: TaintLabel) {
        self.labels.insert(label);
    }

    /// Check if this value has a specific label.
    pub fn has_label(&self, label: TaintLabel) -> bool {
        self.labels.contains(&label)
    }
}

/// Action to take when a taint flow violation is detected.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaintAction {
    /// Block the data flow entirely.
    Block,
    /// Allow but emit a warning.
    Warn,
    /// Allow and log for audit.
    Log,
}

impl fmt::Display for TaintAction {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Block => write!(f, "Block"),
            Self::Warn => write!(f, "Warn"),
            Self::Log => write!(f, "Log"),
        }
    }
}

/// A single rule governing data flow between taint labels.
#[derive(Debug, Clone)]
pub struct TaintRule {
    /// The source label that triggers this rule.
    pub source_label: TaintLabel,
    /// Destinations that this source label is restricted from flowing to.
    pub blocked_destinations: Vec<TaintLabel>,
    /// Action to take when this rule is violated.
    pub action: TaintAction,
}

/// Result of checking a taint flow.
#[derive(Debug, Clone)]
pub struct TaintFlowResult {
    /// Whether the flow is allowed.
    pub allowed: bool,
    /// Violations found (empty if allowed).
    pub violations: Vec<TaintViolation>,
    /// The most severe action among all violations (None if no violations).
    pub action: Option<TaintAction>,
}

/// A single violation of a taint flow rule.
#[derive(Debug, Clone)]
pub struct TaintViolation {
    /// The source label that triggered the violation.
    pub source_label: TaintLabel,
    /// The destination that was blocked.
    pub destination: TaintLabel,
    /// The action prescribed by the violated rule.
    pub action: TaintAction,
}

/// Policy engine for checking information flow between taint labels.
///
/// Evaluates whether data with certain taint labels is allowed to flow
/// to a given destination based on configured rules.
#[derive(Debug, Clone)]
pub struct TaintPolicy {
    rules: Vec<TaintRule>,
}

impl TaintPolicy {
    /// Create a policy with the given rules.
    pub fn new(rules: Vec<TaintRule>) -> Self {
        Self { rules }
    }

    /// Create a policy with sensible default rules.
    ///
    /// Default rules:
    /// - `ShellOutput` cannot flow to `Network` (Warn)
    /// - `SecretEnv` cannot flow to `ShellOutput` (Block)
    /// - `SecretEnv` cannot flow to `Network` (Block)
    /// - `FileContent` cannot flow to `Network` (Warn)
    pub fn with_defaults() -> Self {
        Self::new(vec![
            TaintRule {
                source_label: TaintLabel::ShellOutput,
                blocked_destinations: vec![TaintLabel::Network],
                action: TaintAction::Warn,
            },
            TaintRule {
                source_label: TaintLabel::SecretEnv,
                blocked_destinations: vec![TaintLabel::ShellOutput],
                action: TaintAction::Block,
            },
            TaintRule {
                source_label: TaintLabel::SecretEnv,
                blocked_destinations: vec![TaintLabel::Network],
                action: TaintAction::Block,
            },
            TaintRule {
                source_label: TaintLabel::FileContent,
                blocked_destinations: vec![TaintLabel::Network],
                action: TaintAction::Warn,
            },
        ])
    }

    /// Check whether a tainted value is allowed to flow to the given destination.
    pub fn check_flow(&self, value: &TaintedValue, destination: TaintLabel) -> TaintFlowResult {
        let mut violations = Vec::new();

        for rule in &self.rules {
            if value.has_label(rule.source_label)
                && rule.blocked_destinations.contains(&destination)
            {
                violations.push(TaintViolation {
                    source_label: rule.source_label,
                    destination,
                    action: rule.action,
                });
            }
        }

        let action = violations.iter().map(|v| v.action).max_by_key(|a| match a {
            TaintAction::Log => 0,
            TaintAction::Warn => 1,
            TaintAction::Block => 2,
        });

        let allowed = !violations.iter().any(|v| v.action == TaintAction::Block);

        TaintFlowResult {
            allowed,
            violations,
            action,
        }
    }
}

impl Default for TaintPolicy {
    fn default() -> Self {
        Self::with_defaults()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_tainted_value_creation() {
        let val = TaintedValue::new("data", TaintLabel::UserInput, "keyboard");
        assert_eq!(val.value, "data");
        assert!(val.has_label(TaintLabel::UserInput));
        assert!(!val.has_label(TaintLabel::Network));
        assert_eq!(val.source, "keyboard");
    }

    #[test]
    fn test_tainted_value_add_label() {
        let mut val = TaintedValue::new("data", TaintLabel::UserInput, "keyboard");
        val.add_label(TaintLabel::LlmOutput);
        assert!(val.has_label(TaintLabel::UserInput));
        assert!(val.has_label(TaintLabel::LlmOutput));
    }

    #[test]
    fn test_default_policy_shell_to_network_warns() {
        let policy = TaintPolicy::with_defaults();
        let val = TaintedValue::new("ls output", TaintLabel::ShellOutput, "shell.rs");
        let result = policy.check_flow(&val, TaintLabel::Network);
        assert!(result.allowed); // Warn, not Block
        assert_eq!(result.violations.len(), 1);
        assert_eq!(result.action, Some(TaintAction::Warn));
    }

    #[test]
    fn test_default_policy_secret_to_shell_blocks() {
        let policy = TaintPolicy::with_defaults();
        let val = TaintedValue::new("sk-secret", TaintLabel::SecretEnv, "env:API_KEY");
        let result = policy.check_flow(&val, TaintLabel::ShellOutput);
        assert!(!result.allowed);
        assert_eq!(result.action, Some(TaintAction::Block));
    }

    #[test]
    fn test_default_policy_secret_to_network_blocks() {
        let policy = TaintPolicy::with_defaults();
        let val = TaintedValue::new("sk-secret", TaintLabel::SecretEnv, "env:API_KEY");
        let result = policy.check_flow(&val, TaintLabel::Network);
        assert!(!result.allowed);
        assert_eq!(result.action, Some(TaintAction::Block));
    }

    #[test]
    fn test_default_policy_file_to_network_warns() {
        let policy = TaintPolicy::with_defaults();
        let val = TaintedValue::new("file data", TaintLabel::FileContent, "/etc/passwd");
        let result = policy.check_flow(&val, TaintLabel::Network);
        assert!(result.allowed);
        assert_eq!(result.action, Some(TaintAction::Warn));
    }

    #[test]
    fn test_allowed_flow_no_violations() {
        let policy = TaintPolicy::with_defaults();
        let val = TaintedValue::new("hello", TaintLabel::UserInput, "keyboard");
        let result = policy.check_flow(&val, TaintLabel::Network);
        assert!(result.allowed);
        assert!(result.violations.is_empty());
        assert_eq!(result.action, None);
    }

    #[test]
    fn test_user_input_to_shell_allowed() {
        let policy = TaintPolicy::with_defaults();
        let val = TaintedValue::new("ls -la", TaintLabel::UserInput, "chat.send");
        let result = policy.check_flow(&val, TaintLabel::ShellOutput);
        assert!(result.allowed);
        assert!(result.violations.is_empty());
    }

    #[test]
    fn test_multi_label_worst_action_wins() {
        let policy = TaintPolicy::with_defaults();
        // Value has both ShellOutput (Warn to Network) and SecretEnv (Block to Network)
        let mut val = TaintedValue::new("mixed", TaintLabel::ShellOutput, "mixed source");
        val.add_label(TaintLabel::SecretEnv);
        let result = policy.check_flow(&val, TaintLabel::Network);
        assert!(!result.allowed);
        assert_eq!(result.action, Some(TaintAction::Block));
        assert_eq!(result.violations.len(), 2);
    }

    #[test]
    fn test_custom_policy() {
        let policy = TaintPolicy::new(vec![TaintRule {
            source_label: TaintLabel::LlmOutput,
            blocked_destinations: vec![TaintLabel::ShellOutput],
            action: TaintAction::Block,
        }]);
        let val = TaintedValue::new("rm -rf /", TaintLabel::LlmOutput, "gpt-4");
        let result = policy.check_flow(&val, TaintLabel::ShellOutput);
        assert!(!result.allowed);
    }

    #[test]
    fn test_empty_policy_allows_all() {
        let policy = TaintPolicy::new(vec![]);
        let val = TaintedValue::new("anything", TaintLabel::SecretEnv, "env:TOKEN");
        let result = policy.check_flow(&val, TaintLabel::Network);
        assert!(result.allowed);
        assert!(result.violations.is_empty());
    }

    #[test]
    fn test_taint_label_display() {
        assert_eq!(TaintLabel::Network.to_string(), "Network");
        assert_eq!(TaintLabel::SecretEnv.to_string(), "SecretEnv");
        assert_eq!(TaintLabel::ShellOutput.to_string(), "ShellOutput");
    }

    #[test]
    fn test_taint_action_display() {
        assert_eq!(TaintAction::Block.to_string(), "Block");
        assert_eq!(TaintAction::Warn.to_string(), "Warn");
        assert_eq!(TaintAction::Log.to_string(), "Log");
    }

    #[test]
    fn test_default_trait() {
        let policy = TaintPolicy::default();
        assert_eq!(policy.rules.len(), 4);
    }
}
